    #[test]
    fn tmp_tree_dump_persistent() {
        let source = "function f()\n    persistent a b c\nend\n";
        let tree = parse(source);
        fn walk(node: tree_sitter::Node, source: &str, indent: usize) {
            let text = &source[node.start_byte()..node.end_byte()];
            println!("{}{} {:?}", " ".repeat(indent), node.kind(), text);
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk(child, source, indent + 2);
            }
        }
        walk(tree.root_node(), source, 0);
        let diags = lint_file(&*engine(), source);
        println!("DIAGS: {diags:?}");
    }
